package br.edu.ifms.robotica.dao;
import java.sql.*;import java.time.OffsetDateTime;import br.edu.ifms.robotica.model.TokenRedefinicao;import br.edu.ifms.robotica.seguranca.TokenUtil;import br.edu.ifms.robotica.util.Conexao;
public class TokenRedefinicaoDAO{
 public void inserir(String token,Long estudanteId,Long coordenadorId)throws SQLException{String sql="INSERT INTO token_redefinicao_senha(estudante_id,coordenador_id,token_hash,expira_em) VALUES(?,?,?,?)";try(Connection c=Conexao.conectar();PreparedStatement ps=c.prepareStatement(sql)){if(estudanteId==null)ps.setNull(1,Types.BIGINT);else ps.setLong(1,estudanteId);if(coordenadorId==null)ps.setNull(2,Types.BIGINT);else ps.setLong(2,coordenadorId);ps.setString(3,TokenUtil.hash(token));ps.setObject(4,OffsetDateTime.now().plusMinutes(30));ps.executeUpdate();}}
 public TokenRedefinicao buscarValido(String token)throws SQLException{String sql="SELECT t.id,t.estudante_id,t.coordenador_id FROM token_redefinicao_senha t LEFT JOIN estudante e ON e.id=t.estudante_id LEFT JOIN coordenador c ON c.id=t.coordenador_id WHERE t.token_hash=? AND t.usado_em IS NULL AND t.expira_em>CURRENT_TIMESTAMP AND ((t.estudante_id IS NOT NULL AND e.ativo=TRUE) OR (t.coordenador_id IS NOT NULL AND c.ativo=TRUE))";try(Connection c=Conexao.conectar();PreparedStatement ps=c.prepareStatement(sql)){ps.setString(1,TokenUtil.hash(token));try(ResultSet rs=ps.executeQuery()){if(!rs.next())return null;return mapear(rs);}}}
 public void redefinir(String token,String novoHash)throws SQLException{String hash=TokenUtil.hash(token);try(Connection c=Conexao.conectar()){c.setAutoCommit(false);try{TokenRedefinicao t;String sql="SELECT t.id,t.estudante_id,t.coordenador_id FROM token_redefinicao_senha t LEFT JOIN estudante e ON e.id=t.estudante_id LEFT JOIN coordenador co ON co.id=t.coordenador_id WHERE t.token_hash=? AND t.usado_em IS NULL AND t.expira_em>CURRENT_TIMESTAMP AND ((t.estudante_id IS NOT NULL AND e.ativo=TRUE) OR (t.coordenador_id IS NOT NULL AND co.ativo=TRUE)) FOR UPDATE OF t";try(PreparedStatement ps=c.prepareStatement(sql)){ps.setString(1,hash);try(ResultSet rs=ps.executeQuery()){if(!rs.next())throw new SQLException("Token inválido ou expirado.");t=mapear(rs);}}if(t.getEstudanteId()!=null)new EstudanteDAO().atualizarSenha(c,t.getEstudanteId(),novoHash);else new CoordenadorDAO().atualizarSenha(c,t.getCoordenadorId(),novoHash);try(PreparedStatement ps=c.prepareStatement("UPDATE token_redefinicao_senha SET usado_em=CURRENT_TIMESTAMP WHERE id=? AND usado_em IS NULL")){ps.setLong(1,t.getId());if(ps.executeUpdate()!=1)throw new SQLException("Token já utilizado.");}c.commit();}catch(SQLException e){c.rollback();throw e;}finally{c.setAutoCommit(true);}}}
 private TokenRedefinicao mapear(ResultSet rs)throws SQLException{TokenRedefinicao t=new TokenRedefinicao();t.setId(rs.getLong("id"));long e=rs.getLong("estudante_id");if(!rs.wasNull())t.setEstudanteId(e);long c=rs.getLong("coordenador_id");if(!rs.wasNull())t.setCoordenadorId(c);return t;}
}
